  'À DÉFINIR': { label: 'À DÉFINIR', short: '?', className: 'open' },
  'À TESTER': { label: 'À TESTER', short: 'T', className: 'test' },
  'DÉPENDANT': { label: 'DÉPENDANT', short: 'D', className: 'dependent' },
